#!/usr/bin/env python3
"""Wrap JSON (or plain text) as a classic <script> data file for file://-safe pages.

Pages opened as file:// cannot fetch()/XHR local files in Chrome, so site data is shipped as
JavaScript that registers itself on a global namespace:

    <script src="data/graph.js"></script>          (classic script, no type="module")
    <script> const g = window.VLONTO["graph"]; </script>

Output format (deterministic, no timestamps; re-running on the same input gives identical bytes):

    /* generated by tools/json2js.py from graph.json (sha256 1a2b...) - do not edit */
    (window.VLONTO = window.VLONTO || {})["graph"] = JSON.parse("...JSON text as a JS string...");

JSON.parse of one string literal is faster for V8/JSC/SpiderMonkey to parse than an equivalent
object literal for large data. With --text the file content is stored as a plain JS string
(for Turtle, SPARQL, Markdown ...).

Usage
  json2js.py data/graph.json -o site/data/graph.js            # name = file stem ("graph")
  json2js.py a.json b.json --out-dir site/data                # one .js per input
  json2js.py sample.ttl --text --name sample_ttl -o site/data/sample_ttl.js
  json2js.py big.json -o site/data/big.js --verify            # re-load the .js in Node and compare
Options
  --name NAME      key under window.<var> (default: input stem, non [A-Za-z0-9_-] replaced by _)
  --var VLONTO     global namespace object (default VLONTO)
  --ascii          escape every non-ASCII character as \\uXXXX (output is pure ASCII; immune to
                   charset mistakes). Default keeps UTF-8 text, which needs <meta charset="utf-8">.
  --verify         evaluate the generated file with Node (tools from $V/envs/web) in a sandbox and
                   check the value equals the input; exit 1 on mismatch.
  --node PATH      node executable for --verify (default: `node` on PATH).
  --max-mb N       refuse outputs larger than N MB (default 95; GitHub rejects files > 100 MB).
"""
from __future__ import annotations

import argparse
import hashlib
import json
import re
import shutil
import subprocess
import sys
from pathlib import Path

HEADER = "/* generated by tools/json2js.py from {src} (sha256 {sha}) - do not edit */\n"


def js_string_literal(text: str, ascii_only: bool) -> str:
    """JSON string literal that is also a safe JS string literal (incl. inline <script>)."""
    lit = json.dumps(text, ensure_ascii=ascii_only)
    # U+2028/2029 are legal in ES2019+ string literals but not in older engines: escape them.
    lit = lit.replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    # Keep the file safe to inline inside <script> as well.
    lit = lit.replace("</", "<\\/").replace("<!--", "\\u003C!--")
    return lit


def sanitize(name: str) -> str:
    return re.sub(r"[^A-Za-z0-9_\-]", "_", name)


def convert(src: Path, out: Path, name: str, var: str, as_text: bool, ascii_only: bool, max_mb: float):
    raw = src.read_bytes()
    sha = hashlib.sha256(raw).hexdigest()
    text = raw.decode("utf-8-sig")
    if as_text:
        value = text
        body = js_string_literal(text, ascii_only)
    else:
        try:
            value = json.loads(text)
        except json.JSONDecodeError as e:
            raise SystemExit(f"{src}: invalid JSON: {e}")
        compact = json.dumps(value, ensure_ascii=False, separators=(",", ":"), allow_nan=False)
        body = "JSON.parse(" + js_string_literal(compact, ascii_only) + ")"
    js = (HEADER.format(src=src.name, sha=sha[:16])
          + f'(window.{var} = window.{var} || {{}})[{json.dumps(name)}] = {body};\n')
    data = js.encode("ascii" if ascii_only else "utf-8")
    if len(data) > max_mb * 1024 * 1024:
        raise SystemExit(f"{out}: {len(data)/1e6:.1f} MB exceeds --max-mb {max_mb}; split the data")
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_bytes(data)
    return value, len(data)


NODE_CHECK = r"""
const fs = require('fs'), vm = require('vm');
const [file, varName, key] = process.argv.slice(1);
const ctx = { window: {} }; vm.createContext(ctx);
vm.runInContext(fs.readFileSync(file, 'utf8'), ctx, { filename: file });
const v = ctx.window[varName][key];
process.stdout.write(JSON.stringify(v === undefined ? null : v));
"""


def verify(out: Path, var: str, name: str, value, node: str) -> bool:
    if not shutil.which(node) and not Path(node).exists():
        raise SystemExit(f"--verify: node executable not found: {node}")
    r = subprocess.run([node, "-e", NODE_CHECK, str(out), var, name], capture_output=True)
    if r.returncode != 0:
        print(r.stderr.decode(errors="replace"), file=sys.stderr)
        return False
    return json.loads(r.stdout.decode("utf-8")) == value


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("inputs", nargs="+", type=Path)
    ap.add_argument("-o", "--output", type=Path, help="output .js (single input only)")
    ap.add_argument("--out-dir", type=Path, help="directory for <name>.js outputs")
    ap.add_argument("--name")
    ap.add_argument("--var", default="VLONTO")
    ap.add_argument("--text", action="store_true")
    ap.add_argument("--ascii", action="store_true")
    ap.add_argument("--verify", action="store_true")
    ap.add_argument("--node", default="node")
    ap.add_argument("--max-mb", type=float, default=95.0)
    a = ap.parse_args(argv)
    if not re.fullmatch(r"[A-Za-z_$][A-Za-z0-9_$]*", a.var):
        ap.error("--var must be a JS identifier")
    if a.output and len(a.inputs) != 1:
        ap.error("-o/--output needs exactly one input; use --out-dir for several")
    if a.name and len(a.inputs) != 1:
        ap.error("--name needs exactly one input")
    if not a.output and not a.out_dir:
        ap.error("give -o OUT.js or --out-dir DIR")
    ok = True
    for src in a.inputs:
        name = a.name or sanitize(src.stem)
        out = a.output or (a.out_dir / f"{name}.js")
        value, nbytes = convert(src, out, name, a.var, a.text, a.ascii, a.max_mb)
        line = f"{src} -> {out} [{a.var}[{name!r}], {nbytes:,} bytes]"
        if a.verify:
            good = verify(out, a.var, name, value, a.node)
            ok &= good
            line += " verify=" + ("OK" if good else "MISMATCH")
        print(line)
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())
